import { gsap } from 'gsap';
import {
  Group,
  Mesh,
  PlaneGeometry,
  CylinderGeometry,
  TorusKnotGeometry,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import {
  MeshStandardNodeMaterial,
  MeshPhysicalNodeMaterial,
} from 'three/webgpu';
import {
  uv,
  vec3,
  vec4,
  mix,
  smoothstep,
  texture,
  uniform,
  color,
  normalMap,
  roughnessMap,
  metalnessMap,
} from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new Group();
  const timelines = [];

  // Extract colors from spec
  const colors = config.colors || config.intent?.visualSpec?.colors || {};
  const bgColor = colors.background || '#0b0b10';
  const surfaceColor = colors.surface || '#14141a';
  const accentColor = colors.accent || '#ff2a38';
  const gradientStops = colors.gradientStops || [
    { at: 0, hex: '#0b0b10' },
    { at: 0.7, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];

  // ===== STAGE BACKDROP =====
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({
    color: 0x0b0b10,
  });

  // Build vertical gradient shader
  const backdropUV = uv();
  const gradCol = vec3(0.067, 0.067, 0.082); // #0b0b10
  if (gradientStops && gradientStops.length > 0) {
    const stops = gradientStops.sort((a, b) => a.at - b.at);
    let acc = vec3(0, 0, 0);
    for (let i = 0; i < stops.length; i++) {
      const stop = stops[i];
      const hexStr = stop.hex.replace('#', '');
      const r = parseInt(hexStr.substr(0, 2), 16) / 255;
      const g = parseInt(hexStr.substr(2, 2), 16) / 255;
      const b = parseInt(hexStr.substr(4, 2), 16) / 255;
      const stopCol = vec3(r, g, b);

      const t = backdrop.y * 0.5 + 0.5; // Normalize -1..1 to 0..1
      const lower = i === 0 ? 0 : stops[i - 1].at;
      const upper = stop.at;
      const range = upper - lower;
      const localT =
        range > 0 ? smoothstep(lower, upper, t) : vec3(0, 0, 0);

      if (i === 0) {
        acc = mix(acc, stopCol, smoothstep(0, stops[0].at, t));
      } else {
        acc = mix(acc, stopCol, smoothstep(lower, upper, t));
      }
    }
    backdropMat.colorNode = acc;
  }

  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -3;
  group.add(backdrop);

  // ===== PEDESTAL =====
  const pedestalGeom = new CylinderGeometry(1.1, 1.1, 0.5, 32);
  const pedestalMat = new MeshStandardNodeMaterial({
    color: surfaceColor,
    roughness: 0.7,
    metalness: 0.35,
  });
  const pedestal = new Mesh(pedestalGeom, pedestalMat);
  pedestal.position.y = -0.35;
  group.add(pedestal);

  // ===== TORUS KNOT WITH BRUSHED METAL PBR =====
  const knotGeom = new TorusKnotGeometry(0.7, 0.22, 220, 36);

  // Create node material for knot
  const knotMat = new MeshPhysicalNodeMaterial({
    metalness: 0.55,
    roughness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35,
  });

  // Load roughness map
  let roughnessMapTex = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      roughnessMapTex = tex;
      roughnessMapTex.anisotropy = 16;
      // Apply via tsl node
      knotMat.roughnessNode = mix(
        uniform(0.55),
        roughnessMap(texture(tex)),
        uniform(0.9)
      );
      knotMat.needsUpdate = true;
    });
  }

  // Anisotropy on knot
  knotMat.anisotropy = 0.9;

  const knot = new Mesh(knotGeom, knotMat);
  knot.position.set(0, 0.4, 0);
  // Anisotropy rotation 90 deg to tube direction
  knot.rotation.z = Math.PI / 2;
  group.add(knot);

  // ===== CONTACT SHADOW PLANE =====
  const shadowGeom = new PlaneGeometry(3, 3);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
  });

  // Radial gradient: center opacity 0.6 falling to 0
  const shadowUV = uv();
  const shadowDist = shadowUV.distance(vec3(0.5, 0.5, 0));
  const shadowOpacity = smoothstep(0.4, 0, shadowDist * 1.5);
  shadowMat.opacityNode = mix(
    uniform(0),
    uniform(0.6),
    smoothstep(0.4, 0, shadowDist)
  );
  shadowMat.colorNode = vec3(0, 0, 0);

  const shadowPlane = new Mesh(shadowGeom, shadowMat);
  shadowPlane.position.set(0, -0.36, 0.01);
  shadowPlane.rotation.x = -Math.PI / 2;
  shadowPlane.scale.set(1.5, 1.5, 1.5);
  group.add(shadowPlane);

  // ===== LIGHTING =====
  // Key light
  const keyLight = new ctx.THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(1.5, 2, 1);
  keyLight.castShadow = false;
  group.add(keyLight);

  // Rim/accent light opposite
  const rimLight = new ctx.THREE.DirectionalLight(accentColor, 0.7);
  rimLight.position.set(-1.5, 1, -1);
  group.add(rimLight);

  // Ambient
  const ambientLight = new ctx.THREE.AmbientLight(0xffffff, 0.6);
  group.add(ambientLight);

  // ===== TEXT CONTENT =====
  const textItems =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Headline: "Material study 03"
  const headlineItem = textItems.find((item) =>
    item.text?.includes('Material study')
  );
  if (headlineItem || textItems.length > 0) {
    const headlineText = headlineItem?.text || 'Material study 03';
    const headlineObj = ctx.fontAtlas.createText(headlineText, {
      fontSize: 68,
      color: '#e8ecf2',
      align: 'center',
      letterSpacingPx: -0.005 * 68,
    });
    headlineObj.position.set(0, -1.2, 0.1);
    group.add(headlineObj);
  }

  // Caption: "GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT"
  const captionItem = textItems.find(
    (item) =>
      item.text?.includes('GRADE') || item.text?.includes('TITANIUM')
  );
  if (captionItem || textItems.length > 1) {
    const captionText =
      captionItem?.text || 'GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT';
    const captionObj = ctx.fontAtlas.createText(captionText, {
      fontSize: 18,
      color: '#e8ecf2',
      align: 'center',
      letterSpacingPx: 0.08 * 18,
    });
    captionObj.position.set(0, -1.6, 0.1);
    group.add(captionObj);
  }

  // ===== CINEMATIC PRIMITIVES =====
  const cinematicPrimitives = config.cinematicPrimitives || [];
  const primitiveCleanups = [];

  for (const prim of cinematicPrimitives) {
    if (prim.name === 'orbit' && prim.trigger === 'load') {
      const primResult = ctx.primitives['orbit'](knot, {
        speed: prim.params?.speed || 0.1,
        radius: prim.params?.radius || 0.4,
      });
      if (primResult && primResult.cleanup) {
        primitiveCleanups.push(primResult.cleanup);
      }
    }
  }

  // ===== CLEANUP =====
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    // Kill all GSAP timelines
    timelines.forEach((tl) => tl.kill());
    gsap.killTweensOf([knot, group]);

    // Call primitive cleanups
    primitiveCleanups.forEach((cleanup) => cleanup());

    // Dispose materials and geometries
    backdropGeom.dispose();
    backdropMat.dispose();

    pedestalGeom.dispose();
    pedestalMat.dispose();

    knotGeom.dispose();
    knotMat.dispose();

    shadowGeom.dispose();
    shadowMat.dispose();

    if (roughnessMapTex) {
      roughnessMapTex.dispose();
    }
  };

  return group;
}
